export default function TaskInterface({task, act}) {
  const t = task || {};
  const m = t.merchant || {};
  const intent = t.intent || {};
  const list = v => Array.isArray(v) ? v : [];
  const text = v => v == null || v === '' ? 'Unknown' : typeof v === 'object' ? JSON.stringify(v) : String(v);
  const labels = {original_payment:'Original payment method',store_credit:'Store credit',qr_dropoff:'Printer-free QR drop-off',print_label:'Print a shipping label'};
  const label = v => labels[v] || text(v);
  const money = v => {
    if (typeof v !== 'number' || !Number.isFinite(v) || !m.currency) return 'Unknown';
    try { return new Intl.NumberFormat('en-US',{style:'currency',currency:m.currency}).format(v / 100); } catch (err) { return 'Unknown currency'; }
  };
  const [chosen, setChosen] = React.useState({});
  const [methodChanged, setMethodChanged] = React.useState(false);
  const initial = !task || t.status === 'not_started';
  const busy = !!t.progress || ['working','created','submitting'].includes(t.status);
  const unverified = t.status === 'submitted_unverified';
  const submitted = unverified || ['submitted','completed','complete'].includes(t.status);
  const locked = initial || busy || !!t.receipt || typeof act !== 'function';
  const editLocked = locked || submitted;
  const reasons = list(m.reasons).filter(x => x && x.value);
  const methods = list(m.methods).filter(x => x && ['print_label','qr_dropoff'].includes(x.value));
  const lines = list(m.lines).filter(Boolean);
  const selected = Array.isArray(m.selectedLines) ? m.selectedLines.map(x => x && typeof x === 'object' ? x.id : x) : null;
  const shoes = lines.filter(x => /red.*shoe|shoe.*red/i.test((x.name || '') + ' ' + (x.variant || '')));
  const requestedDestination = intent.refundDestination || 'original_payment';
  const requestedMethod = chosen.method || (intent.noPrinter !== false ? 'qr_dropoff' : null);
  const methodValue = chosen.method || m.method || '';
  const reasonValue = chosen.reason === undefined ? t.reason || '' : chosen.reason;
  const checks = list(t.checks).filter(Boolean);
  const badChecks = checks.filter(c => ['fail','failed','conflict','mismatch','error'].includes(c.status));
  const destinationConflict = !!m.refundDestination && m.refundDestination !== requestedDestination;
  const methodConflict = !!m.method && !!requestedMethod && m.method !== requestedMethod;
  const printerConflict = intent.noPrinter !== false && methodValue === 'print_label';
  const itemConflict = selected !== null && lines.length > 0 && (selected.some(id => !shoes.some(x => x.id === id)) || shoes.some(x => !selected.includes(x.id)));
  const reasonConflict = !!chosen.reason && !!t.reason && chosen.reason !== t.reason;
  const conflict = destinationConflict || methodConflict || printerConflict || itemConflict || reasonConflict || badChecks.length > 0;
  const unknown = !m.method || !m.refundDestination || !t.reason || !m.currency || selected === null || !shoes.length || typeof m.deductionCents !== 'number' || typeof m.expectedRefundCents !== 'number';
  const choose = (key, value) => {
    if (editLocked || !value) return;
    setChosen(prior => ({...prior,[key]:value}));
    if (key === 'method') setMethodChanged(true);
    act('choice',{[key]:value});
  };
  const check = repair => { if (!locked && !(repair && submitted)) act('check',{repair}); };
  const discovery = t.discovery || {};
  const fallbackScreens = [{id:'home',name:'Your next chapter, outside.'},{id:'orders',name:'Your orders'},{id:'shop',name:'Shop the collection'}];
  const fallbackFlows = [{name:'My orders',exit:'orders'},{name:'View orders & delivery',exit:'home'},{name:'View product & options →',exit:'home'},{name:'Browse all products',exit:'shop'}];
  const screens = list(discovery.screens).length ? discovery.screens : fallbackScreens;
  const flows = (list(discovery.flows).length ? discovery.flows : fallbackFlows).slice().sort((a,b) => Number(/return|order/i.test(b.name || '')) - Number(/return|order/i.test(a.name || '')));
  const statusMessage = t.receipt ? 'The host has supplied a receipt. Review the receipt and its independent saved-confirmation result; editing is disabled.' : unverified ? 'Submitted, but saved confirmation is not verified. Matching draft terms are not proof of a saved return. Check the saved confirmation; do not submit again.' : t.status === 'submitting' ? 'The host is sending the approved request. No saved confirmation is available yet. Elapsed time is not confirmation.' : busy ? 'The host is updating the task. Controls are temporarily disabled.' : t.error ? 'An error needs attention. No successful return is claimed.' : initial ? 'Not started. Review the observed routes, then use Start this task in the trusted host.' : submitted ? 'The host reports a submitted or completed state, but no receipt is available here. Check for saved confirmation before treating this as complete.' : conflict ? 'Requested choices differ from the source. Review the differences, restore your choices and validate again.' : unknown ? 'Some required source terms are unknown. Validate to inspect them before exact approval.' : 'Review and validate the current terms. Validation does not submit the return.';
  const methodDetail = methods.find(x => x.value === methodValue);
  return <main className="generated-root">
    <header className="generated-header"><strong>Northstar Outfitters</strong><span>Synthetic records · Sandbox only</span></header>
    <div className="generated-content">
      <p className="generated-eyebrow">A considered return</p>
      <h1>Return the red shoes.<br/>Keep the jacket.</h1>
      <p className="generated-intro">Your request: no printer, shoes only, refund to original payment.</p>
      <section className="generated-status" role="status" aria-live="polite" aria-atomic="true"><strong>{initial ? 'Task overview' : 'Live task status'}</strong><p>{statusMessage}</p><span className="generated-small">Host state: {text(t.status)}</span></section>
      {t.error && <section className="generated-warning" role="alert"><h2>Task error</h2><p>{text(t.error)}</p></section>}
      {(unverified || t.status === 'submitting' || (submitted && !t.receipt)) && <section className="generated-warning"><h2>Saved confirmation still needed</h2><p>A completed return requires a specific saved-confirmation result from the host, not a wait or matching draft checks.</p>{busy ? <p>If the host remains blank or stuck, use the trusted host’s inspection or recovery path to verify the saved request. This interface cannot reload the host or resubmit the request.</p> : <><p>Use this read-only check to ask the host to inspect the saved state. If confirmation remains unavailable, the outcome stays unverified; use the host’s recovery path rather than submitting again.</p><button type="button" className="generated-primary" disabled={locked} onClick={() => check(false)}>Check saved confirmation</button></>}</section>}
      {initial ? <>
        <section className="generated-panel"><p className="generated-eyebrow">Supported task</p><h2>Only the shoes are going back</h2><ul><li>Return only red shoes.</li><li><strong>Keep jacket.</strong></li><li>Use a printer-free method.</li><li>Preserve original-payment preference.</li></ul><p>The trusted host supplies <strong>Start this task</strong> for this synthetic return, followed by exact approval of the current terms. Nothing starts from this overview.</p></section>
        <section className="generated-panel"><h2>Observed return alternatives</h2><div className="generated-routes"><section className="generated-route generated-priority"><span className="generated-tag">Fits the no-printer goal</span><h3>Printer-free QR drop-off</h3><p>Reached: saved return draft, only shoes selected, jacket kept.</p><p>A method deduction applies. Selecting this method changed the observed refund destination to <strong>store credit</strong>, despite the earlier original-payment choice.</p><p>Your preference remains original payment. Restore any conflict and validate before approval.</p></section><section className="generated-route"><span className="generated-tag">Requires a printer</span><h3>Print a shipping label</h3><p>Reached: saved return draft, only shoes selected, jacket kept, original payment selected.</p><p>Requires printing and attaching a label, so it does not fit your no-printer request.</p></section></div><p className="generated-small">Current fees and refund amounts will come from live task data. Neither observed draft establishes a submitted return or saved confirmation.</p></section>
        <section className="generated-panel"><h2>Other observed routes</h2><p className="generated-small">Informational only. Route names do not establish what was reached.</p><div className="generated-routes">{flows.map((f,i) => { const reached = f.currentObservation?.reached || f.exit; const screen = screens.find(s => s.id === reached); return <section className="generated-route" key={f.id || i}><h3>{text(f.name)}</h3><p><strong>Reached:</strong> {screen ? text(screen.name) : 'Unknown reached screen'}</p><p className="generated-small">No execution control for this route.</p></section>; })}</div><p className="generated-small">Initial exploration was incomplete at the budget limit. The red-shoes product path was not reached, and a source exception was recorded. Separate return-draft observations are shown above.</p></section>
      </> : <>
        <div className="generated-grid"><div>
          <section className="generated-panel"><p className="generated-eyebrow">01 · Items</p><h2>Return only red shoes</h2><div className="generated-preference"><strong>Keep jacket</strong><p>Requested scope is fixed here. Source selection is listed separately.</p></div>{lines.length ? <ul className="generated-items">{lines.map((line,i) => <li key={line.id || i}><strong>{text(line.name)}</strong>{line.variant && <p className="generated-small">{text(line.variant)}</p>}<p>Observed source: <strong>{selected === null ? 'Unknown selection' : selected.includes(line.id) ? 'Included in return' : 'Not included in return'}</strong></p>{/jacket/i.test(line.name || '') && <span className="generated-tag">Keep jacket · requested</span>}</li>)}</ul> : <p>Source items: Unknown.</p>}{selected !== null && <p className="generated-small">Observed selected IDs: {selected.length ? selected.map(text).join(', ') : 'None'}</p>}</section>
          <section className="generated-panel"><p className="generated-eyebrow">02 · Choices</p><h2>How to return the shoes</h2><div className="generated-field"><label htmlFor="generated-reason">Return reason</label><select id="generated-reason" value={reasonValue} disabled={editLocked || !reasons.length} onChange={e => choose('reason',e.target.value)}><option value="">Choose a reason</option>{reasonValue && !reasons.some(r => r.value === reasonValue) && <option value={reasonValue}>{text(reasonValue)}</option>}{reasons.map(r => <option key={r.value} value={r.value}>{r.label || r.value}</option>)}</select><p className="generated-small">Observed reason: {reasons.find(r => r.value === t.reason)?.label || text(t.reason)}</p>{!reasons.length && <p className="generated-small">Available reasons are unknown.</p>}</div>
          <div className="generated-field"><label htmlFor="generated-method">Return method</label><select id="generated-method" value={methodValue} disabled={editLocked || !methods.length} onChange={e => choose('method',e.target.value)}><option value="">Choose a method</option>{methodValue && !methods.some(x => x.value === methodValue) && <option value={methodValue}>{label(methodValue)}</option>}{methods.map(x => <option key={x.value} value={x.value}>{x.label || label(x.value)}</option>)}</select><p className="generated-small">Selected choice: {label(methodValue)}</p><p className="generated-small">Observed source: {label(m.method)}</p>{methodDetail?.detail && <p className="generated-small">{text(methodDetail.detail)}</p>}{!methods.length && <p className="generated-small">Available methods are unknown.</p>}</div>
          <p className="generated-note">Changing the return method can change the source refund destination. It does not change your original-payment preference.</p>{methodChanged && <p className="generated-note">Method changed. Review the current deduction and destination, then validate again.</p>}<div className="generated-preference"><strong>Requested refund destination</strong><p>{label(requestedDestination)}</p><span className="generated-small">Your intent, not a claim about the source.</span></div></section>
        </div><section className="generated-panel generated-review"><p className="generated-eyebrow">03 · Source review</p><h2>Current terms</h2><p className="generated-small">Current task data, not proof of a completed return.</p><dl className="generated-terms"><div><dt>Observed method</dt><dd>{label(m.method)}</dd></div><div><dt>Method fee / deduction</dt><dd>{money(m.deductionCents)}</dd></div><div><dt>Observed refund destination</dt><dd>{label(m.refundDestination)}</dd></div><div><dt>Expected refund</dt><dd className="generated-amount">{money(m.expectedRefundCents)}</dd></div></dl>{unknown && <p className="generated-note">Required terms are still unknown. Resolve them before dependent approval or completion.</p>}<p className="generated-small">A saved draft is not a saved return confirmation.</p></section></div>
        {conflict && <section className="generated-warning" role="alert"><h2>Source conflict</h2>{destinationConflict && <p><strong>Requested:</strong> {label(requestedDestination)}<br/><strong>Observed destination:</strong> {label(m.refundDestination)}</p>}{(methodConflict || printerConflict) && <p><strong>Requested goal:</strong> printer-free return<br/><strong>Selected method:</strong> {label(methodValue)}<br/><strong>Observed method:</strong> {label(m.method)}</p>}{itemConflict && <p><strong>Requested:</strong> only red shoes; keep jacket.<br/><strong>Observed selected IDs:</strong> {selected.length ? selected.map(text).join(', ') : 'None'}</p>}{reasonConflict && <p><strong>Selected reason:</strong> {text(chosen.reason)}<br/><strong>Observed reason:</strong> {text(t.reason)}</p>}{badChecks.length > 0 && <p>Additional checks report a mismatch or error; review their exact values below.</p>}{!submitted && <><p>Restore reapplies your choices without submitting.</p><button type="button" className="generated-secondary" disabled={locked} onClick={() => check(true)}>Restore my choices</button></>}</section>}
        <section className="generated-panel"><h2>{submitted ? 'Reported source checks' : 'Validate before exact approval'}</h2><p>{submitted ? 'These checks describe the reported source terms. Matching values alone do not verify a saved confirmation.' : 'Validate the items, method, deduction and destination. The trusted host handles exact approval, submission and independent saved-confirmation verification.'}</p>{checks.length > 0 ? <ul className="generated-checks">{checks.map((c,i) => <li key={c.key || i}><strong>{text(c.label)}</strong><span className="generated-tag">{text(c.status)}</span><p>Expected: {text(c.expected)}<br/>Observed: {text(c.observed)}</p></li>)}</ul> : <p className="generated-small">No source checks are available yet.</p>}{!submitted && !t.receipt && <div className="generated-actions"><button type="button" className="generated-primary" disabled={locked} onClick={() => check(false)}>Validate current choices</button>{!conflict && <button type="button" className="generated-secondary" disabled={locked} onClick={() => check(true)}>Restore my choices</button>}</div>}{t.validation != null && <details className="generated-details"><summary>Host validation details</summary><pre>{text(t.validation)}</pre></details>}</section>
        {t.receipt && <section className="generated-panel"><h2>Host receipt</h2><p>The host supplied the record below. Use its independent verification result to determine whether the saved confirmation is verified; this interface does not infer success from elapsed time.</p><pre className="generated-record">{text(t.receipt)}</pre></section>}
      </>}
      <footer className="generated-footer">Synthetic records only · No production access · Exact approval and completion remain with the trusted host.</footer>
    </div>
  </main>;
}
